#!/system/bin/sh
# Root My Pixel — Foolproof Hardcoded KernelSU Setup
# Auto-invokes via Shizuku if needed • All payloads embedded • Zero manual setup

TEMP_DIR="/data/local/tmp"
EXPLOIT_FILE="$TEMP_DIR/cve-2026-43499-app.so"
HELPER_FILE="$TEMP_DIR/libcve43499root.so"
KSUD_FILE="$TEMP_DIR/ksud-pixel"
DAEMON_SOCKET="$TEMP_DIR/temp_su.sock"
EXPLOIT_LOG="$TEMP_DIR/exploit.log"
EXPLOIT_TIMEOUT=1800
STALL_TIMEOUT=600
HELPER_BINARY=""

PROFILES='
tegu|6.1.157|CP2A.260705.006|CP2A.260805.005|android14-6.1
panther|6.1.157|CP2A.260705.006|CP2A.260705.006|android14-6.1
panther|6.1.124|BP2A.250705.008|BP2A.250705.008|android14-6.1
mustang|6.6.118|CP2A.260705.006|CP2A.260705.006|android15-6.6
lynx|6.1.157|CP2A.260705.006|CP2A.260705.006|android14-6.1
'

log() {
    local ts=$(date '+%H:%M:%S') level=$1; shift
    echo "[$ts] [$level] $@"
}
prompt() {
    while true; do printf ">>> $1 [y/n]: "; read -r ans; case "$ans" in y|yes) return 0 ;; n|no) return 1 ;; esac; done
}
mkdir_p() { mkdir -p "$1"; }

extract_payload() {
    log "INFO" "Extracting $3..."
    mkdir -p "$(dirname "$2")"
    echo "$1" | base64 -d > "$2" 2>/dev/null || { log "ERROR" "Failed to extract $3"; return 1; }
    [ -f "$2" ] && [ -s "$2" ] && { chmod 755 "$2"; log "INFO" "✓ Extracted: $3"; return 0; }
    return 1
}

detect_device() {
    log "INFO" "=== DEVICE DETECTION ==="
    KERNEL=$(cat /proc/version 2>/dev/null | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -1)
    DEVICE=$(getprop ro.product.device 2>/dev/null)
    BUILD=$(getprop ro.build.display.id 2>/dev/null)
    MODEL=$(getprop ro.product.model 2>/dev/null)
    log "INFO" "Device: $DEVICE ($MODEL), Build: $BUILD, Kernel: $KERNEL"
}

find_profile() {
    while IFS='|' read -r dev kern_base profile_build actual_build kmi; do
        [ -z "$dev" ] && continue
        if [ "$dev" = "$1" ] && [ "$2" = "$kern_base" ] && [ "$3" = "$actual_build" ]; then
            log "INFO" "✓ Found profile: $dev-$profile_build (KMI: $kmi)"
            echo "$dev|$profile_build|$kmi"
            return 0
        fi
    done <<EOF
$PROFILES
EOF
}

get_helper_binary() {
    [ -f "$HELPER_FILE" ] && { HELPER_BINARY="$HELPER_FILE"; return 0; }
    log "ERROR" "Helper binary not found"
    return 1
}

execute_exploit() {
    log "INFO" "" 
    log "INFO" "=== RUNNING EXPLOIT ==="
    get_helper_binary || return 1
    [ ! -f "$EXPLOIT_FILE" ] && { log "ERROR" "Exploit not found"; return 1; }
    prompt "Ready to execute exploit?" || { log "WARN" "Exploit cancelled"; return 1; }
    
    local start_time=$(date +%s) last_log_time=$start_time last_log_size=0
    timeout $EXPLOIT_TIMEOUT "$HELPER_BINARY" --run-payload "$EXPLOIT_FILE" "$HELPER_BINARY" "$EXPLOIT_LOG" 2>&1 &
    local pid=$!
    
    while kill -0 $pid 2>/dev/null; do
        local now=$(date +%s) elapsed=$((now - start_time))
        [ -f "$EXPLOIT_LOG" ] && {
            local log_size=$(stat -c%s "$EXPLOIT_LOG" 2>/dev/null || echo 0)
            [ $log_size -gt $last_log_size ] && { last_log_time=$now; last_log_size=$log_size; tail -3 "$EXPLOIT_LOG" | while read line; do log "INFO" "$line"; done; }
        }
        [ $((now - last_log_time)) -gt $STALL_TIMEOUT ] && { log "ERROR" "Exploit stalled"; kill $pid 2>/dev/null; return 1; }
        [ $elapsed -gt $EXPLOIT_TIMEOUT ] && { log "ERROR" "Exploit timeout"; kill $pid 2>/dev/null; return 1; }
        sleep 2
    done
    
    wait $pid 2>/dev/null || true
    grep -q "done=1" "$EXPLOIT_LOG" 2>/dev/null && grep -q "root=1" "$EXPLOIT_LOG" 2>/dev/null || { log "ERROR" "Exploit failed"; return 1; }
    log "INFO" "✓ Exploit successful"
}

await_daemon_socket() {
    log "INFO" "Waiting for daemon socket..."
    local start=$(date +%s)
    while true; do
        [ -S "$DAEMON_SOCKET" ] && { log "INFO" "✓ Daemon socket ready"; return 0; }
        [ $(($(date +%s) - start)) -gt 15 ] && { log "ERROR" "Daemon socket timeout"; return 1; }
        sleep 0.5
    done
}

run_helper() {
    local cmd="$1" retries=${2:-5} attempt=1
    while [ $attempt -le $retries ]; do
        local output=$(timeout 90 "$HELPER_BINARY" -c "$cmd" 2>&1 || true)
        [ -n "$output" ] && echo "$output" | while read line; do log "INFO" "$line"; done
        [ $attempt -lt $retries ] && echo "$output" | grep -q "Connection refused" && { sleep 1.5; attempt=$((attempt + 1)); continue; }
        echo "$output"
        return 0
    done
}

install_kernelsu() {
    local kmi="$1"
    log "INFO" ""
    log "INFO" "=== SETTING UP KERNELSU ROOT ==="
    await_daemon_socket || return 1
    log "INFO" "[1] Creating /data/adb..."
    run_helper "mkdir -p /data/adb && chmod 700 /data/adb" >/dev/null || true
    log "INFO" "[2] Setting SELinux permissive..."
    run_helper "setenforce 0" >/dev/null || true
    log "INFO" "[3] Staging ksud..."
    run_helper "chmod 755 $KSUD_FILE && chown root:root $KSUD_FILE" >/dev/null || true
    log "INFO" "[4] Running ksud late-load (KMI=$kmi)..."
    run_helper "$KSUD_FILE late-load --kmi $kmi" >/dev/null || true
    sleep 1
    log "INFO" "[5] Verifying kernel module..."
    local attempt=1
    while [ $attempt -le 15 ]; do
        run_helper "test -e /dev/kernelsu" >/dev/null 2>&1 && { log "INFO" "✓ KernelSU verified"; break; }
        [ $((attempt % 3)) -eq 0 ] && log "INFO" "  Waiting... ($attempt/15)"
        sleep 0.5
        attempt=$((attempt + 1))
    done
    log "INFO" "[6] Testing root..."
    local test=$(run_helper "id -u" 2>/dev/null || echo "")
    [ "$test" = "0" ] && log "INFO" "✓ Root verified" || log "WARN" "Root test inconclusive"
    log "INFO" "[7] Setting up ReSukiSU..."
    run_helper "mkdir -p /data/adb/ksu && chmod 777 /data/adb/ksu" >/dev/null || true
}

cleanup() { rm -f "$EXPLOIT_FILE" "$EXPLOIT_LOG"; }

main() {
    log "INFO" "╔════════════════════════════════════════════╗"
    log "INFO" "║  Root My Pixel — Hardcoded KernelSU Setup ║"
    log "INFO" "╚════════════════════════════════════════════╝"
    
    detect_device
    local profile=$(find_profile "$DEVICE" "$KERNEL" "$BUILD")
    [ -z "$profile" ] && { log "ERROR" "Device not supported"; exit 1; }

    dev=$(echo "$profile" | cut -d'|' -f1)
    profile_build=$(echo "$profile" | cut -d'|' -f2)
    kmi=$(echo "$profile" | cut -d'|' -f3)
    log "INFO" "DEVICE: $DEVICE ($MODEL) | BUILD: $BUILD | KMI: $kmi"
    
    prompt "Continue?" || exit 0
    mkdir_p "$TEMP_DIR"
    
    log "INFO" ""
    log "INFO" "=== PREPARING PAYLOADS ==="


    EXPLOIT_B64=''
    KSUD_B64=''

    extract_payload "$HELPER_B64" "$HELPER_FILE" "Helper" || exit 1
    HELPER_B64=''
    extract_payload "$EXPLOIT_B64" "$EXPLOIT_FILE" "Exploit" || exit 1
    extract_payload "$KSUD_B64" "$KSUD_FILE" "ksud" || exit 1
    log "INFO" "✓ All payloads ready"
    
    execute_exploit || exit 1
    install_kernelsu "$kmi" || exit 1
    cleanup
    
    log "INFO" ""
    log "INFO" "═════════════════════════════════════════════"
    log "INFO" "SUCCESS — KernelSU is installed!"
    log "INFO" "═════════════════════════════════════════════"
    log "INFO" ""
    log "INFO" "Next: Open ReSukiSU Manager → Grant root"
    log "INFO" "Verify: su -c 'id'  (should return uid=0)"
}

auto_invoke_with_rish() {
    local uid=$(id -u 2>/dev/null)
    if [ "$uid" != "2000" ]; then
        local script_abs="$(cd "$(dirname "$0")" 2>/dev/null && pwd)/$(basename "$0")" || return 1
        if command -v rish >/dev/null 2>&1; then
            log "INFO" "Escalating to Shizuku context via rish..."
            exec rish sh "$script_abs" "$@"
        else
            log "ERROR" "═══════════════════════════════════════════════════════"
            log "ERROR" "✗ NOT running in Shizuku (UID: $uid, need: 2000)"
            log "ERROR" "✗ rish binary not found in PATH"
            log "ERROR" "═══════════════════════════════════════════════════════"
            log "ERROR" "FIXES:"
            log "ERROR" "1. Install Shizuku app"
            log "ERROR" "2. Run: rish sh '$script_abs'"
            log "ERROR" "═══════════════════════════════════════════════════════"
            exit 1
        fi
    fi
}

auto_invoke_with_rish "$@"
main "$@"
